def start(m,title,topics):
 banks[m]={'moduleId':m,'title':title,'topics':[{'id':m+'-'+t[0],'title':t[1],'pages':t[2]} for t in topics], 'questions':[], 'limitations':[]}

def add(m,t,c,l,p,stem,choices,explanation,wrong):
 pages=p if isinstance(p,list) else [p]
 sources=[]
 for page in pages:
  if (m,page) in visual:
   sources.append({'page':page,'quote':visual[(m,page)],'type':'visual','note':'Nhãn/chú thích đã đọc trực tiếp trên hình của slide; câu hỏi không hiển thị hình.'})
  else:
   txt=next(x['text'] for x in docs[m]['pages'] if x['page']==page).strip()
   sources.append({'page':page,'quote':txt,'type':'text'})
 i=len(banks[m]['questions'])+1
 assert len(choices)==4 and len(set(choices))==4 and len(wrong)==3
 banks[m]['questions'].append({'id':f'{m}-q{i:03}','topicId':m+'-'+t,'conceptId':m+'-'+c,'level':{'u':'understand','a':'apply','h':'analyze'}[l], 'stem':stem,'options':choices,'answer':0,'explanation':explanation,'optionExplanations':[explanation]+wrong,'sources':sources,'review':{'source':False,'semantic':False,'coverage':False}})

def save():
 for m,b in banks.items():
  # Rotate the correct slot without changing option-to-explanation correspondence.
  for i,q in enumerate(b['questions']):
   n=i%4
   q['options']=q['options'][n:]+q['options'][:n]
   q['optionExplanations']=q['optionExplanations'][n:]+q['optionExplanations'][:n]
   q['answer']=(-n)%4
  (BANKS/f'{m}.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
  print(m,len(b['questions']),{lv:sum(q['level']==lv for q in b['questions']) for lv in ['understand','apply','analyze']})

