add('m09','dong-noan','thu-tinh-noanchin','a',11,'Trong bài, sự kiện nào cần có khi chuyển sang mô tả noãn chín?', ['Hiện tượng thụ tinh','Chỉ bắt đầu hình thành một hàng tế bào vuông','Chỉ xuất hiện một hàng tế bào dẹt','Chỉ đạt thời kỳ bào thai tuần 8'], 'Slide 11 nêu noãn chín khi có hiện tượng thụ tinh.', ['Đặc điểm của nang sơ cấp, không đủ xác định noãn chín.','Đặc điểm của nang nguyên thủy.','Giai đoạn khởi đầu giảm phân không phải noãn chín.'])
add('m09','nang-noan','phanbiet-mot-nhieu','a',[16,18],'Hai mẫu đều có noãn bào 1 và màng trong suốt; mẫu A có một hàng vuông, mẫu B nhiều hàng. Ghép loại nang nào phù hợp?', ['A sơ cấp; B thứ cấp','A thứ cấp; B sơ cấp','Cả hai nguyên thủy','Cả hai bắt buộc là nang chín'], 'Khác biệt số hàng tế bào trong mô tả cho phép ghép sơ cấp với A, thứ cấp với B.', ['Hoán đổi đặc điểm số hàng.','Nang nguyên thủy được mô tả là một hàng dẹt.','Các dữ kiện này chưa cho thấy cả hai là nang chín.'])
add('m09','nang-noan','khong-du-hoc','a',[18,21],'Chỉ biết “nang có hốc”, có thể khẳng định noãn bên trong đã là noãn bào 2 hay chưa?', ['Chưa; nang thứ cấp có thể có hốc mà vẫn chứa noãn bào 1','Có; cứ có hốc là noãn bào 2','Có; mọi nang có hốc đã được thụ tinh','Không; vì nang chín không bao giờ có hốc'], 'Slide 18 cho thấy nang thứ cấp chuyển sang có hốc nhưng vẫn chứa noãn bào 1; slide 21 mới nêu chuyển 1→2 ở nang chín.', ['Đã bỏ qua nang thứ cấp có hốc.','Có hốc không đồng nghĩa đã thụ tinh.','Slide 21 nêu nang chín có hốc.'])
add('m09','dong-noan','kiemtra-nhan-dinh-lh','a',[10,11],'Một ghi chú viết: “Sau đỉnh LH, noãn bào 2 đã là noãn chín dù chưa thụ tinh”. Cần sửa điểm nào?', ['Noãn bào 2 vẫn dừng ở kỳ giữa II; noãn chín gắn với thụ tinh','Đổi LH thành apoptosis là đủ','Đổi noãn bào 2 thành noãn nguyên bào là đủ','Bỏ điều kiện thụ tinh vì hoàn toàn không liên quan'], 'Slide 10 nêu điểm dừng kỳ giữa II; slide 11 nêu noãn chín khi có thụ tinh.', ['Apoptosis không thay thế tín hiệu LH trong mô tả này.','Noãn nguyên bào không phải giai đoạn sau LH.','Thụ tinh là điều kiện được nêu cho noãn chín.'])
add('m09','nang-noan','kiemtra-det-zona','a',[14,16],'Một sinh viên mô tả “nang nguyên thủy có một hàng tế bào vuông, bắt đầu tạo zona pellucida”. Nên sửa tên nang thành gì?', ['Nang sơ cấp','Nang chín','Hoàng thể','Nang thứ cấp nhiều hàng'], 'Một hàng tế bào vuông và bắt đầu tạo màng trong suốt là mô tả của nang sơ cấp.', ['Nang chín có nhiều hàng và hốc.','Không phải mô tả hoàng thể.','Nang thứ cấp được mô tả có nhiều hàng.'])
add('m09','nang-noan','khong-danhdong-noan','a',[16,18],'Một nang sơ cấp phát triển thêm nhiều hàng tế bào và chuyển thành nang thứ cấp. Theo bài, noãn bên trong phải đổi từ noãn bào 1 sang noãn bào 2 ngay không?', ['Không; cả hai giai đoạn đều được mô tả chứa noãn bào 1','Có; cứ tăng số hàng là hoàn thành giảm phân II','Có; nang thứ cấp luôn chứa noãn chín sau thụ tinh','Không; vì nang thứ cấp không còn chứa noãn'], 'Slide 16 và 18 đều ghi noãn bào 1, dù cấu trúc tế bào bao quanh đã đổi.', ['Số hàng tế bào không chứng minh hoàn thành giảm phân II.','Slide 18 nêu noãn bào 1.','Nang thứ cấp vẫn chứa noãn.'])
add('m09','dong-noan','duongkinh-noanchin','a',11,'Theo đường kính khoảng 0,1 mm của noãn chín ghi trong bài, cách đổi đơn vị nào đúng?', ['Khoảng 100 µm','Khoảng 1 µm','Khoảng 10 mm','Khoảng 100 cm'], '0,1 mm × 1.000 = 100 µm. Đây là đổi đơn vị của số liệu trên slide 11.', ['1 µm tương đương 0,001 mm.','10 mm lớn hơn số liệu 100 lần.','100 cm không tương đương 0,1 mm.'])
add('m09','dong-noan','thai7thang','a',7,'Tại mốc tháng thứ 7 thai kỳ trong bài, phần lớn noãn nguyên bào đã chuyển thành dạng nào?', ['Noãn bào 1','Noãn bào 2 sau đỉnh LH','Noãn chín sau thụ tinh','Hoàng thể'], 'Slide 7 ghi đến tháng thứ 7 hầu hết thành noãn bào 1.', ['Không phải mốc tạo noãn bào 2 sau LH.','Không có thụ tinh của các noãn ở bào thai.','Hoàng thể không phải tên giai đoạn của dòng noãn.'])
add('m09','nang-noan','phanbiet-nang-noan-mau','a',[14,16],'Mẫu A và B đều có noãn bào 1 nhưng hàng tế bào quanh A dẹt, quanh B vuông. Khi ghi kết quả, cách nào giữ được thông tin đúng?', ['Ghi cùng loại noãn bào nhưng khác giai đoạn nang','Ghi A là noãn bào 1 và B là noãn chín','Ghi cả hai là nang nguyên thủy vì đều có noãn bào 1','Bỏ khác biệt hình dạng tế bào quanh noãn'], 'Điểm chung là noãn bào 1; điểm khác là nang nguyên thủy so với nang sơ cấp.', ['Hình dạng tế bào quanh noãn không chứng minh noãn chín.','Bỏ qua tiêu chí dẹt/vuông phân biệt hai nang.','Mất dấu hiệu cần để phân giai đoạn nang.'])
add('m09','dong-noan','germinal-vesicle','a',12,'Một noãn được mô tả còn nguyên túi mầm (germinal vesicle), nhiễm sắc chất dừng ở prophase I. Phát biểu nào phù hợp chú thích slide 12?', ['Trưởng thành giảm phân chưa bắt đầu','Đã thải thể cực thứ nhất và dừng ở metaphase II','Đã hoàn tất giảm phân II','Đã hợp nhất hai tiền nhân'], 'Chú thích slide 12 gọi trạng thái túi mầm còn nguyên là immature và cho biết meiotic maturation has not begun.', ['Đó là mô tả giai đoạn C, khác trạng thái đang cho.','Chưa bắt đầu trưởng thành giảm phân nên không thể đã hoàn tất II.','Bài không gắn trạng thái túi mầm này với hợp nhất tiền nhân.'])
add('m09','dong-noan','gvbd','a',12,'Trong chú thích slide 12, túi mầm đã vỡ và giảm phân I đang tiếp tục. Có thể kết luận nào?', ['Noãn đã rời trạng thái túi mầm nguyên vẹn để tiếp tục giảm phân I','Noãn chắc chắn đã hoàn thành giảm phân II','Noãn quay về nguyên phân','Noãn không còn trải qua giảm phân I'], 'Chú thích giai đoạn B nêu meiosis I has resumed, with breakdown of the germinal vesicle.', ['Nguồn chỉ mô tả tiếp tục lần I.','Không mô tả quay lại nguyên phân.','Nguồn khẳng định giảm phân I đang tiếp tục.'])

# Vận dụng cao: ghép hai tiến trình, đánh giá tính đủ của bằng chứng và sửa mô hình.
add('m09','tich-hop','mohinh-haichuoi','h',[4,6,14,16,18], 'Một mô hình ghép “nang nguyên thủy–noãn nguyên bào; nang sơ cấp–noãn bào 1; nang thứ cấp–noãn bào 2” theo số thứ tự. Vì sao cách ghép này không đúng với bài?', ['Giai đoạn nang và giai đoạn noãn không ghép một-một; cả ba loại nang được mô tả có noãn bào 1','Tên nang luôn phải trùng số của tên noãn','Nang nguyên thủy phải chứa noãn chín','Mọi nang thứ cấp đều đã qua thụ tinh'], 'Phải đọc cấu trúc nang độc lập với tiến trình tế bào; slide 14,16,18 đều nêu noãn bào 1.', ['Đây chính là giả định sai của mô hình.','Slide 14 ghi noãn bào 1.','Không có cơ sở đồng nhất nang thứ cấp với đã thụ tinh.'])
add('m09','tich-hop','cua-so-sau-lh','h',[9,10,11], 'Theo dõi một noãn từ kỳ đầu I, sau đỉnh LH thấy nó dừng ở kỳ giữa II nhưng chưa thụ tinh. Tổ hợp kết luận nào đúng?', ['Đã hoàn thành giảm phân I; chưa được gọi là noãn chín theo slide 11','Chưa hoàn thành giảm phân I; đã là noãn chín','Đã hoàn thành cả hai lần giảm phân; không cần thụ tinh','Đã quay về noãn nguyên bào; sắp nguyên phân'], 'Kết hợp điểm dừng ban đầu, tác động LH và điều kiện noãn chín: lần I đã xong, lần II vẫn dừng và chưa thụ tinh.', ['Kỳ giữa II là sau hoàn thành lần I; chưa thụ tinh.','Bỏ qua điểm dừng kỳ giữa II.','Không có diễn tiến quay về nguyên bào.'])
add('m09','tich-hop','phanloai-hoc-va-cuccau','h',[12,18,21], 'Hai nang cùng có hốc. Chỉ mẫu B được mô tả noãn đã thải thể cực thứ nhất và dừng ở metaphase II. Cách suy luận nào chặt chẽ nhất?', ['Có hốc chưa đủ phân giai đoạn noãn; dữ kiện thể cực và điểm dừng xác nhận B đã qua giảm phân I','Có hốc chứng minh cả A và B đều đã thụ tinh','B có thể cực nên chắc chắn chưa bắt đầu giảm phân I','A và B phải cùng giai đoạn noãn vì cùng có hốc'], 'Slide 18 cho phép có hốc khi còn noãn bào 1; chú thích slide 12 xác định trạng thái sau lần I bằng thể cực thứ nhất và metaphase II.', ['Hốc nang không là bằng chứng thụ tinh.','Thể cực thứ nhất và metaphase II cho thấy đã qua lần I.','Đồng nhất giai đoạn nang với giai đoạn noãn.'])
add('m09','tich-hop','apoptosis-va-so-luong','h',[7,9,14], 'Một bảng chỉ ghi sự phát triển từ noãn nguyên bào đến các dạng sau rồi kết luận “mọi noãn ban đầu đều sẽ trưởng thành”. Dữ kiện nào của bài bác bỏ kết luận đó?', ['Apoptosis và sự giảm dần số lượng noãn/nang','Có nhiều tên gọi khác nhau của nang','Noãn chín có đường kính khoảng 0,1 mm','Có một hàng tế bào vuông ở nang sơ cấp'], 'Slide 7,9 nêu apoptosis và slide 14 nêu số lượng giảm dần; chuỗi giai đoạn không có nghĩa mọi phần tử đều đi đến cuối.', ['Số tên gọi không chứng minh mất noãn.','Kích thước không bác bỏ tỷ lệ trưởng thành.','Hình dạng tế bào bao quanh không đủ chứng minh quần thể giảm.'])
add('m09','tich-hop','thongtin-toithieu-nang','h',[14,16,18], 'Muốn phân biệt ba nang nguyên thủy, sơ cấp và thứ cấp đều chứa noãn bào 1, bộ thông tin bổ sung nào hữu ích nhất theo bài?', ['Hình dạng và số hàng tế bào bao quanh noãn, cùng cấu trúc màng/hốc','Chỉ xác nhận lại rằng cả ba đều có noãn bào 1','Chỉ đo đường kính của một noãn chín khác','Chỉ hỏi có đỉnh LH hay không rồi bỏ mô tả nang'], 'Các slide phân biệt một hàng dẹt, một hàng vuông, nhiều hàng; màng trong suốt và hốc giúp bổ sung mô tả.', ['Lặp lại dữ kiện không phân biệt được.','Không phải đặc điểm của ba nang đang xét.','Bỏ mất các dấu hiệu trực tiếp của nang trong bài.'])
add('m09','tich-hop','nham-socap-thucap','h',[16,18,10], 'Người học cho rằng “nang chuyển sơ cấp→thứ cấp tức là noãn hoàn thành giảm phân I”. Phân tích nào sửa đúng cả hai phần?', ['Nang thay đổi số hàng tế bào nhưng vẫn có noãn bào 1; hoàn thành giảm phân I được gắn với đỉnh LH','Nang thứ cấp vẫn chỉ có một hàng vuông, còn LH không liên quan','Nang sơ cấp đã chứa noãn chín, nên không cần xét giảm phân','Tên thứ cấp đồng nghĩa mọi cấu trúc trong nang đều đã hoàn thành lần I'], 'Slide 16/18 giữ noãn bào 1 trong hai giai đoạn nang; slide 10 mới liên hệ hoàn thành lần I với đỉnh LH.', ['Sai mô tả nhiều hàng và sai vai trò LH.','Slide 16 ghi noãn bào 1.','Suy luận theo tên gọi thay cho bằng chứng.'])
add('m09','tich-hop','giai-doan-vs-ket-cuc','h',[7,10,11], 'Ba mốc “bào thai tháng 7”, “sau đỉnh LH và dừng kỳ giữa II”, “có thụ tinh” được ghép lần lượt với dạng nào?', ['Noãn bào 1; noãn bào 2; noãn chín','Noãn bào 2; noãn chín; noãn nguyên bào','Noãn chín; noãn bào 1; noãn bào 2','Noãn nguyên bào; nang sơ cấp; hoàng thể'], 'Slide 7 gắn tháng 7 với noãn bào 1, slide 10 gắn sau LH với noãn bào 2, slide 11 gắn thụ tinh với noãn chín.', ['Các mốc không theo mô tả nguồn.','Đảo các giai đoạn.','Trộn tên tế bào, tên nang và hoàng thể.'])
add('m09','tich-hop','ketqua-dua-tren-gv','h',[9,10,12], 'Hai báo cáo: A “túi mầm nguyên vẹn, kỳ đầu I”; B “thể cực thứ nhất đã ra, metaphase II”. Đánh giá nào đúng?', ['A còn ở trạng thái noãn bào 1; B đã qua giảm phân I và ở trạng thái noãn bào 2','A đã qua giảm phân I, B chưa bắt đầu','Cả A và B đều đã hoàn thành giảm phân II','Chỉ khác hình dạng, không liên quan tiến trình giảm phân'], 'Kết hợp mô tả slide 9/10 với chú thích slide 12 xác định hai mức trưởng thành giảm phân khác nhau.', ['Đảo trạng thái A và B.','B vẫn ở điểm dừng kỳ giữa II.','Các chú thích trực tiếp gắn hình thái với giảm phân.'])
add('m09','tich-hop','nang-chin-chua-thutinh','h',[10,11,21], 'Một nang được gọi là “nang chín” và noãn đang chuyển 1→2. Có nên kết luận noãn đó đã là “noãn chín sau thụ tinh” không?', ['Không; tên nang chín không thay thế điều kiện thụ tinh của noãn chín','Có; hai cụm “chín” luôn đồng nghĩa','Có; mọi nang có hốc đều chứa hợp tử','Không; vì nang chín không chứa noãn nào'], 'Slide 21 mô tả nang chín ở giai đoạn noãn 1→2; slide 11 gắn noãn chín với thụ tinh. Không đồng nhất hai thuật ngữ.', ['Bỏ qua hai đối tượng khác nhau.','Hốc nang không chứng minh hợp tử.','Slide 21 nêu rõ noãn bên trong.'])
add('m09','tich-hop','dong-thoi-phattrien','h',[9,14,16,18], 'Một quần thể có nang ở nhiều giai đoạn nhưng nhiều noãn vẫn ở kỳ đầu I. Có nhất thiết là dữ liệu tự mâu thuẫn không?', ['Không; nang có thể khác giai đoạn cấu trúc trong khi đều chứa noãn bào 1','Có; mọi thay đổi của nang buộc noãn tiến thêm một lần giảm phân','Có; chỉ một loại nang được chứa noãn bào 1','Không; vì kỳ đầu I là trạng thái của mọi noãn chín sau thụ tinh'], 'Slide 14,16,18 cùng chứa noãn bào 1, còn slide 9 xác định điểm dừng kỳ đầu I của dạng này.', ['Nguồn không cho phép suy luận một-một đó.','Có ba loại nang cùng được mô tả chứa noãn bào 1.','Noãn chín không được mô tả dừng kỳ đầu I.'])

banks['m09']['limitations']=['Có 40 câu được soạn từ phạm vi rõ ràng; chưa đạt mục tiêu khoảng100 câu và không nhân bản để bù số lượng.','Không dùng số lượng 30.000 ở slide9 vì cần làm rõ với đồ thị slide8.','Không dùng mũi tên noãn nguyên bào→nang nguyên thủy ở slide22 vì không nhất quán với slide14.','Ba lượt duyệt chưa hoàn tất: lượt bao quát độc lập còn chờ.']

