add('m10','cautruc','nhan-dau','u',3,'Cách ghép cấu trúc với vùng của tinh trùng nào phù hợp bài?', ['Nhân thuộc phần đầu','Nhân nằm ở đầu tận của đuôi','Thể cực đầu nằm ở cuối roi','Ty thể tạo thành nhân'], 'Slide 3 đặt nhãn nucleus trong head của tinh trùng.', ['Không phù hợp vị trí nhân trên sơ đồ.','Acrosome được vẽ ở phần đầu.','Ty thể và nhân là hai cấu trúc được ghi riêng.'])
add('m10','cautruc','tythe-doangiua','u',3,'Sơ đồ cấu tạo trong bài gắn cụm ty thể với vùng nào?', ['Đoạn giữa','Nhân ở đầu','Mặt ngoài toàn bộ thể cực đầu','Đầu tận cùng của đuôi'], 'Nhãn mitochondria trỏ vào mid-piece trên slide 3.', ['Nhân được ghi riêng trong head.','Không phải vị trí nhãn ty thể.','Nhãn ty thể nằm ở đoạn giữa, gần đầu.'])
add('m10','cautruc','cuctdau-golgi','u',6,'Sơ đồ biệt hóa tinh tử liên hệ bộ máy Golgi với cấu trúc nào đang hình thành?', ['Thể cực đầu','Nhân thứ hai ở đuôi','Ống dẫn tinh','Hàng rào máu–tinh hoàn'], 'Slide 6 đặt thể Golgi cạnh thể cực đầu trong giai đoạn đầu của biệt hóa tinh tử.', ['Sơ đồ không hình thành nhân thứ hai ở đuôi.','Ống dẫn tinh là cấu trúc cơ quan, không bào quan hình thành từ Golgi ở đây.','Hàng rào không được tạo thành từ Golgi của tinh tử trong sơ đồ.'])
add('m10','sinhtinh','chuoi-sinhtinh','u',5,'Trình tự dòng tế bào nào đúng theo sơ đồ sinh tinh?', ['Tinh nguyên bào → tinh bào I → tinh bào II → tinh tử → tinh trùng','Tinh tử → tinh nguyên bào → tinh trùng → tinh bào II','Tinh bào II → tinh bào I → tinh nguyên bào → tinh trùng','Tinh nguyên bào → tinh trùng → tinh bào I → tinh tử'], 'Các mũi tên slide 5 nối lần lượt năm giai đoạn nêu trong đáp án.', ['Đảo thứ tự trước và sau giảm phân.','Đảo ngược ba giai đoạn đầu.','Tinh trùng là giai đoạn cuối, không trước tinh bào I.'])
add('m10','sinhtinh','giamphan-I','u',5,'Chuyển tiếp nào trên sơ đồ được gắn nhãn giảm phân I?', ['Tinh bào I → tinh bào II','Tinh bào II → tinh tử','Tinh tử → tinh trùng','Tế bào mầm → tinh nguyên bào bằng nguyên phân'], 'Giảm phân I nối tinh bào bậc 1 với tinh bào bậc 2 trên slide 5.', ['Đây là giảm phân II.','Đây là biến đổi thành tinh trùng, không nhãn giảm phân I.','Được gắn nhãn nguyên phân.'])
add('m10','sinhtinh','giamphan-II','u',5,'Tinh tử xuất hiện trực tiếp sau bước nào trong sơ đồ?', ['Giảm phân II của tinh bào II','Nguyên phân của tinh trùng trưởng thành','Giảm phân I của tinh tử','Biến đổi ngược của tế bào Sertoli'], 'Slide 5 cho thấy tinh bào II qua giảm phân II tạo tinh tử.', ['Không có bước nguyên phân của tinh trùng trên sơ đồ.','Tinh tử là sản phẩm sau lần II, không tế bào đi vào lần I.','Sertoli không thuộc chuỗi tế bào mầm này.'])
add('m10','sertoli','nangdo-vs-dongmam','u',10,'Vì sao bài gọi Sertoli là tế bào “điều dưỡng” của tinh bào?', ['Do nâng đỡ, bảo vệ và điều hòa dinh dưỡng','Do trực tiếp biến thành mọi tinh trùng','Do thay nhân cho tinh bào khi giảm phân','Do là tên khác của thể cực đầu'], 'Slide 10 liệt kê nâng đỡ, bảo vệ, điều hòa dinh dưỡng ở Sertoli.', ['Không phải chức năng được mô tả của Sertoli.','Không có cơ chế thay nhân trong bài.','Thể cực đầu là cấu trúc của tinh trùng.'])
add('m10','sertoli','sanpham-che-tiet','u',10,'Nhóm nào gồm các sản phẩm chế tiết của Sertoli được nêu trong bài?', ['Dịch, ABP, inhibin','Chỉ có thể cực đầu và roi','Chỉ có tinh bào I và tinh bào II','Bàng quang, niệu quản, niệu đạo'], 'Slide 10 liệt kê dịch, ABP và inhibin dưới chức năng chế tiết.', ['Đây là cấu trúc của tinh trùng.','Đây là các giai đoạn tế bào dòng tinh.','Đây là cấu trúc giải phẫu, không sản phẩm chế tiết.'])
add('m10','sertoli','thucbao','u',10,'Vai trò thực bào của Sertoli trong bài được mô tả là gì?', ['Thu dọn các sản phẩm dư thừa','Tạo thêm tinh bào bằng giảm phân','Đưa tinh trùng qua niệu quản','Tạo nhân tinh trùng từ ty thể'], 'Slide 10 nêu thực bào các sản phẩm dư thừa.', ['Không phải chức năng thực bào được nêu.','Niệu quản không được nêu là đường tinh trùng.','Không có quá trình chuyển ty thể thành nhân.'])
add('m10','vanchuyen','nieuquan-nieudao','u',12,'Trong sơ đồ đường vận chuyển, niệu quản và niệu đạo có phải cùng một ống không?', ['Không; được ghi riêng, niệu quản đi vào bàng quang còn niệu đạo chạy qua dương vật','Có; chỉ là hai tên của cùng đoạn ống dẫn tinh','Có; cả hai đều là tên của mào tinh','Không; niệu đạo nằm bên trong nhân tinh trùng'], 'Slide 12 vẽ và ghi hai đường khác nhau: niệu quản đi vào bàng quang, niệu đạo đi xuống qua dương vật.', ['Sơ đồ phân biệt chúng với ống dẫn tinh.','Mào tinh được ghi ở cạnh tinh hoàn.','Niệu đạo là cấu trúc cơ quan.'])

add('m10','sinhtinh','nhan-dang-tebao-2n','a',5,'Trong một mô hình sinh tinh, tế bào 2n chuẩn bị thực hiện giảm phân I được gắn tên nào?', ['Tinh bào I','Tinh bào II','Tinh tử','Tinh trùng'], 'Sơ đồ slide 5 ghi tinh bào bậc 1 là 2n trước lần giảm phân I.', ['Tinh bào II nằm sau lần I và được ghi n.','Tinh tử nằm sau lần II và được ghi n.','Tinh trùng là sản phẩm cuối.'])
add('m10','sinhtinh','nhan-dang-sau-I','a',5,'Một tế bào nằm ngay sau giảm phân I nhưng chưa thực hiện giảm phân II. Xếp vào dạng nào?', ['Tinh bào II','Tinh nguyên bào','Tinh tử','Tinh trùng'], 'Vị trí giữa hai lần giảm phân trên slide 5 là tinh bào bậc 2.', ['Tinh nguyên bào ở trước tinh bào I.','Tinh tử xuất hiện sau lần II.','Tinh trùng nằm sau biệt hóa tinh tử.'])
add('m10','sinhtinh','nhan-dang-sau-II','a',[5,6],'Một tế bào đã hoàn tất giảm phân II nhưng đang chuẩn bị kéo dài đầu và tạo đuôi. Tên phù hợp nhất là gì?', ['Tinh tử','Tinh nguyên bào','Tinh bào I','Tế bào Sertoli'], 'Slide 5 cho tinh tử sau giảm phân II; slide 6 mô tả biến đổi của tinh tử thành tinh trùng.', ['Tinh nguyên bào ở giai đoạn trước giảm phân.','Tinh bào I chưa hoàn tất hai lần giảm phân.','Sertoli là tế bào hỗ trợ, không giai đoạn này.'])
add('m10','cautruc','xep-vung-acrosome','a',3,'Một bản mô tả ghi “thể cực đầu phủ vùng đầu chứa nhân”. Đánh giá nào phù hợp sơ đồ cấu tạo?', ['Phù hợp với vị trí acrosome và nucleus trên sơ đồ','Sai vì acrosome nằm ở cuối roi','Sai vì nhân ở đoạn giữa','Sai vì tinh trùng không có phần đầu'], 'Slide 3 ghi acrosome ở phần đầu, cạnh vùng chứa nucleus.', ['Sơ đồ không đặt acrosome ở cuối roi.','Nhân được ghi trong phần đầu.','Sơ đồ ghi rõ head.'])
add('m10','cautruc','xep-vung-axoneme','a',3,'Khi chuyển mô tả sơ đồ sang văn bản, “axoneme” nên được liên hệ với phần nào?', ['Trục của đuôi/roi','Nhân trong đầu','Ống dẫn tinh','Nang noãn'], 'Nhãn axoneme trên slide 3 trỏ vào phần tail/flagellum.', ['Nucleus được ghi riêng trong đầu.','Ống dẫn tinh không thuộc cấu trúc bên trong tinh trùng.','Nang noãn không xuất hiện trong sơ đồ tinh trùng này.'])
add('m10','cautruc','biet-hoa-tythe','a',6,'Trong quá trình biệt hóa tinh tử, mô tả ty thể tập trung gần vùng nối đầu–đuôi phù hợp tên vùng nào của tinh trùng cuối cùng?', ['Đoạn giữa','Thể cực đầu','Nhân','Đầu tận của roi'], 'Slide 6 theo dõi ty lạp thể đến vùng đoạn giữa ở tinh trùng hình thành.', ['Thể cực đầu ở phía đầu, không vùng tập trung ty thể.','Nhân và ty thể được ghi riêng.','Hình không đặt ty thể tại đầu tận roi.'])
add('m10','cautruc','du-thua','a',6,'Một mô tả biệt hóa nói tinh tử giữ nguyên toàn bộ khối bào tương ban đầu. Chi tiết nào trong bài cần dùng để sửa?', ['Có phần bào tương thừa được tách ra trong quá trình tạo hình tinh trùng','Có hình thành thêm một bàng quang trong tinh tử','Nhân biến thành ty thể','Đuôi biến thành thể Golgi'], 'Slide 6 đánh dấu bào tương thừa ở giai đoạn biến đổi hình thái.', ['Bàng quang không phải bào quan của tinh tử.','Không có mũi tên biến nhân thành ty thể.','Không có diễn tiến đuôi thành Golgi.'])
add('m10','sertoli','mohinh-thieu-thucbao','a',10,'Trong mô hình chức năng Sertoli, nâng đỡ và chế tiết được giữ lại nhưng việc thu dọn sản phẩm dư thừa bị bỏ qua. Chức năng nào còn thiếu?', ['Thực bào','Giảm phân I','Tạo túi tinh','Dẫn nước tiểu'], 'Thu dọn sản phẩm dư thừa tương ứng chức năng thực bào trên slide 10.', ['Giảm phân I thuộc dòng tinh, không chức năng này của Sertoli.','Túi tinh là cơ quan riêng.','Không phải chức năng của Sertoli trong bài.'])
add('m10','sertoli','mohinh-thieu-che-tiet','a',10,'Một bảng chức năng Sertoli đã có nâng đỡ và thực bào. Muốn bổ sung chức năng tạo dịch, ABP và inhibin, nên thêm mục nào?', ['Chế tiết','Giảm phân II','Vận chuyển qua niệu quản','Tạo màng trong suốt'], 'Dịch, ABP, inhibin nằm trong mục chế tiết ở slide 10.', ['Không phải tiến trình tạo ba sản phẩm này.','Không liên quan chức năng Sertoli được nêu.','Màng trong suốt không được liệt kê trong sản phẩm Sertoli.'])
add('m10','sertoli','hangrao','a',10,'Khi lập bảng về hàng rào máu–tinh hoàn theo bài, loại tế bào nào cần được đưa vào mục chức năng liên quan?', ['Sertoli','Tinh trùng trưởng thành','Tinh tử đơn độc','Tế bào của bàng quang'], 'Slide 10 liệt kê hàng rào máu–tinh hoàn trong các chức năng của Sertoli.', ['Không được bài giao vai trò này.','Không được bài giao vai trò hàng rào.','Không thuộc môi trường ống sinh tinh được mô tả.'])
add('m10','sinhtinh','vi-tri-ong','a',5,'Muốn quan sát nơi các tế bào dòng tinh phân chia theo sơ đồ bài học, nên hướng đến cấu trúc nào?', ['Ống sinh tinh trong tinh hoàn','Bàng quang','Niệu quản','Túi tinh'], 'Slide 5 chú thích ống sinh tinh là nơi tế bào phân chia.', ['Sơ đồ không gắn phân chia dòng tinh với bàng quang.','Niệu quản không là nơi sinh tinh được nêu.','Túi tinh không được sơ đồ chỉ là nơi phân chia dòng tinh.'])
add('m10','sinhtinh','daythi','a',5,'Mốc tuổi nào được ghi bên cạnh tinh bào I bắt đầu giảm phân trên sơ đồ?', ['Từ tuổi dậy thì','Chỉ trước khi sinh','Chỉ sau mãn dục','Ngay sau thụ tinh của noãn'], 'Chú thích slide 5 ghi “từ tuổi dậy thì bắt đầu giảm phân”.', ['Không phải mốc được ghi trong sơ đồ.','Không phải mốc được ghi.','Không liên quan mốc của tinh bào I trong sơ đồ.'])
add('m10','sinhtinh','so-tinh-tu','a',5,'Theo mô hình lý tưởng trong sơ đồ, một tinh bào I đi hết hai lần giảm phân, không mất tế bào, tạo bao nhiêu tinh tử?', ['4','1','2','8'], 'Slide 5 cho một tinh bào I thành hai tinh bào II rồi bốn tinh tử.', ['Bỏ qua hai lần phân chia.','Mới là số tinh bào II sau lần I.','Không có lần phân chia thứ ba trong sơ đồ.'])
add('m10','cautruc','n-khong-doi-biet-hoa','a',13,'Một ghi chú cho rằng tinh tử phải tăng từ n lên 2n mới thành tinh trùng. Cách sửa nào đúng với sơ đồ?', ['Giữ n ở cả tiền tinh trùng và tinh trùng','Giữ 2n ở cả hai','Đổi tinh trùng thành 4n','Bỏ hoàn toàn giai đoạn tiền tinh trùng'], 'Slide 13 ghi tiền tinh trùng (n) và tinh trùng (n), không tăng bội thể ở bước biệt hóa.', ['Không khớp nhãn n của hai giai đoạn.','Không có nhãn 4n ở tinh trùng.','Giai đoạn tiền tinh trùng vẫn có trên sơ đồ.'])
add('m10','sertoli','khoang-ke','a',11,'Một mô tả đặt tế bào Leydig và mạch máu ở khoang kẽ ngoài biểu mô ống sinh tinh. Mô tả ấy thế nào so với sơ đồ?', ['Phù hợp vị trí các nhãn trong slide 11','Sai vì mạch máu nằm trong nhân tinh trùng','Sai vì Leydig là tên của thể cực đầu','Sai vì không có khoang kẽ trong sơ đồ'], 'Slide 11 ghi interstitial compartment với Leydig cell và blood vessel phía ngoài ống.', ['Mạch máu là cấu trúc ngoài ống, không trong nhân.','Leydig cell là nhãn tế bào riêng.','Sơ đồ ghi rõ interstitial compartment.'])
add('m10','sertoli','thu-tu-tu-day-den-long','a',11,'Trong sơ đồ tổ chức ống sinh tinh, chuỗi từ vùng đáy hướng về phía lòng ống phù hợp nhất là gì?', ['Tinh nguyên bào → tinh bào → tinh tử → tinh trùng','Tinh trùng → tinh tử → tinh bào → tinh nguyên bào','Mạch máu → thể cực đầu → bàng quang → tinh trùng','Tế bào Leydig → niệu quản → tinh tử → nhân'], 'Các nhãn spermatogonia, spermatocytes, spermatids và spermatozoa được bố trí từ vùng đáy lên phía lòng trên slide 11.', ['Là hướng ngược.','Trộn các cấu trúc không thuộc chuỗi dòng tinh trong ống.','Trộn khoang kẽ, đường tiết niệu và tế bào.'])
add('m10','vanchuyen','mao-tinh','a',12,'Trong mô tả đường đi, cấu trúc áp sát tinh hoàn rồi liên tục với ống dẫn tinh là gì?', ['Mào tinh hoàn','Niệu quản','Bàng quang','Thể cực đầu'], 'Slide 12 đặt mào tinh cạnh tinh hoàn, nối tiếp với ống dẫn tinh.', ['Niệu quản đi vào bàng quang.','Bàng quang là khoang ở phía trên, không ôm sát tinh hoàn.','Thể cực đầu thuộc từng tinh trùng.'])
add('m10','vanchuyen','ong-dan-tinh','a',12,'Một sơ đồ chữ vẽ đường từ mào tinh đi lên vùng chậu. Nhãn nào đúng cho ống đó?', ['Ống dẫn tinh','Niệu quản','Niệu đạo trong dương vật','Ống sinh tinh trong nhân'], 'Đường từ mào tinh lên vùng chậu được ghi ống dẫn tinh trên slide 12.', ['Niệu quản không xuất phát từ mào tinh.','Niệu đạo là đường đi xuống qua dương vật trong hình.','Ống sinh tinh không nằm trong nhân.'])
add('m10','vanchuyen','tien-liet','a',12,'Theo sơ đồ, tuyến nằm dưới bàng quang và bao quanh đoạn đầu của niệu đạo được ghi là gì?', ['Tuyến tiền liệt','Tinh hoàn','Mào tinh','Túi tinh nằm sau bàng quang'], 'Nhãn tuyến tiền liệt ở slide 12 trỏ tới tuyến dưới bàng quang quanh niệu đạo.', ['Tinh hoàn nằm trong bìu.','Mào tinh áp sát tinh hoàn.','Túi tinh được ghi ở vị trí khác phía sau bàng quang.'])
add('m10','cautruc','bo-phan-so-voi-te-bao','a',[3,10],'Một bảng gộp “nhân, thể cực đầu, Sertoli” thành ba bộ phận của cùng một tinh trùng. Sửa mục nào?', ['Tách Sertoli thành loại tế bào hỗ trợ riêng','Tách nhân vì tinh trùng không có nhân','Tách thể cực đầu vì nó nằm ở bàng quang','Gộp tất cả thành tên khác của đuôi'], 'Slide 3 mô tả nhân/thể cực đầu là cấu trúc tinh trùng; slide 10 mô tả Sertoli là tế bào điều dưỡng.', ['Sơ đồ có nhãn nucleus.','Acrosome được ghi ở phần đầu tinh trùng.','Không phải các tên đồng nghĩa của đuôi.'])

add('m10','tichhop','n-va-hinhdang','h',[5,6,13],'Hai mẫu đều có bộ NST n; một còn dạng tinh tử, một có đầu–đoạn giữa–đuôi rõ. Kết luận nào đúng theo bài?', ['Cùng n không đồng nghĩa cùng mức biệt hóa; tinh tử còn trải qua biến đổi hình thái thành tinh trùng','Mẫu có đuôi bắt buộc là 2n','Mẫu chưa có đuôi bắt buộc chưa giảm phân I','Cả hai phải là tinh nguyên bào vì cùng bộ NST'], 'Slide 13 giữ n từ tiền tinh trùng đến tinh trùng; slide 6 cho thấy biệt hóa hình thái ở giai đoạn này.', ['Tinh trùng được ghi n.','Tinh tử đã nằm sau giảm phân II.','Tinh nguyên bào được ghi 2n trên slide 5.'])
add('m10','tichhop','stop-I-vs-II','h',5,'Trong mô hình có hai nhóm: nhóm A dừng trước giảm phân I; nhóm B đã qua giảm phân I nhưng chưa qua II. Tổ hợp mô tả nào đúng?', ['A còn tinh bào I 2n; B có tinh bào II n','A có tinh tử n; B có tinh nguyên bào 2n','Cả hai đều có tinh trùng trưởng thành','A có tinh bào II n; B có tinh bào I 2n'], 'Dựa vào vị trí trước/sau lần I và nhãn 2n/n trên slide 5, hai nhóm có giai đoạn và bội thể khác nhau.', ['Đảo vị trí giai đoạn và bội thể.','Cả hai đều chưa hoàn thành toàn bộ sơ đồ.','Hoán đổi nhóm A và B.'])
add('m10','tichhop','dem-theo-nhanh','h',5,'Trong mô hình một tinh bào I tạo hai tinh bào II, một tinh bào II không tiếp tục, tinh bào II còn lại hoàn tất giảm phân II. Không giả định tăng sinh bù, tối đa có bao nhiêu tinh tử từ dòng này?', ['2','4','8','1'], 'Mỗi tinh bào II trên sơ đồ tạo hai tinh tử. Chỉ một nhánh còn đi hết lần II nên tạo hai, không phải bốn.', ['Bốn đòi hỏi cả hai nhánh tinh bào II cùng hoàn tất.','Không có hai lần nhân đôi số tế bào nữa.','Tinh bào II hoàn tất lần II cho hai tế bào theo mô hình.'])
add('m10','tichhop','taohinh-vs-phan-chia','h',[5,6],'Một sinh viên đặt “giảm phân III” giữa tinh tử và tinh trùng vì thấy tế bào đổi hình dạng. Phản biện nào có căn cứ?', ['Sơ đồ chỉ có hai lần giảm phân; bước tinh tử→tinh trùng mô tả tạo thể cực đầu, đuôi và loại bào tương thừa','Mọi đổi hình dạng đều là một lần giảm phân','Tinh tử chưa trải qua giảm phân nào','Tinh trùng phải phân chia lần III để trở thành tinh bào I'], 'Slide 5 chỉ ghi lần I và II; slide 6 mô tả biệt hóa tinh tử, không thêm phân bào giảm nhiễm.', ['Đổi hình dạng không đủ chứng minh phân chia.','Tinh tử là sản phẩm sau giảm phân II.','Đảo chiều phát triển và thêm bước không có nguồn.'])
add('m10','tichhop','sertoli-va-du-thua','h',[6,10],'Sơ đồ biệt hóa cho thấy bào tương thừa, còn phần Sertoli nêu thực bào sản phẩm dư thừa. Liên hệ nào hợp lý trong phạm vi bài?', ['Hai nội dung nối việc tạo sản phẩm dư thừa với chức năng thu dọn của Sertoli','Bào tương thừa phải biến thành tinh bào I mới','Sertoli phải giảm phân II để thu dọn','Bào tương thừa tạo thành niệu quản'], 'Có thể kết nối sản phẩm thừa trong biệt hóa với vai trò thực bào được bài giao cho Sertoli; không thêm cơ chế ngoài nguồn.', ['Không có diễn tiến quay về tinh bào I.','Thực bào không được mô tả bằng giảm phân II.','Niệu quản không hình thành từ bào tương tinh tử trong bài.'])
add('m10','tichhop','hai-muc-tochuc','h',[3,5,12],'Một bản tổng hợp đặt “thể cực đầu → tinh hoàn → tinh bào II → niệu đạo” làm chuỗi giai đoạn tế bào. Cách sửa phù hợp nhất là gì?', ['Tách bộ phận tinh trùng, giai đoạn dòng tinh và cấu trúc đường dẫn thành ba mức mô tả','Đổi tất cả thành tinh bào II vì cùng hệ sinh dục','Giữ nguyên vì mũi tên có thể nối bất kỳ cấu trúc nào','Chỉ đổi niệu đạo thành niệu quản để hoàn chỉnh chuỗi'], 'Thể cực đầu là bộ phận, tinh bào II là giai đoạn tế bào, còn tinh hoàn/niệu đạo là cấu trúc cơ quan. Ba slide mô tả ba mức khác nhau.', ['Không phải cùng loại đối tượng.','Mũi tên trình tự phải thể hiện quan hệ có nguồn.','Đổi sang niệu quản vẫn không tạo chuỗi dòng tế bào.'])
add('m10','tichhop','phanbiet-ong-va-khoangke','h',[5,11],'Hai mô tả được đưa ra: (1) dòng tinh phân chia trong ống sinh tinh; (2) Leydig và mạch máu nằm ở khoang kẽ. Có mâu thuẫn không?', ['Không; đây là hai khoang/cấu trúc khác nhau được thể hiện trong bài','Có; mọi tế bào trong tinh hoàn đều nằm trong lòng ống','Có; mạch máu phải là một giai đoạn của tinh bào','Không; vì Leydig là tên khác của tinh trùng'], 'Slide 5 chỉ nơi sinh tinh; slide 11 phân biệt ống sinh tinh với interstitial compartment chứa Leydig và mạch máu.', ['Bỏ qua khoang kẽ được vẽ rõ.','Mạch máu không là một giai đoạn dòng tinh.','Leydig và spermatozoa được ghi ở vị trí khác nhau.'])
add('m10','tichhop','hangrao-dinhduong','h',10,'Một mô hình Sertoli chỉ kiểm tra thực bào và bỏ qua các vai trò còn lại. Vì sao chưa đủ để đại diện toàn bộ chức năng Sertoli trong bài?', ['Bài còn nêu nâng đỡ, bảo vệ, dinh dưỡng, chế tiết và hàng rào máu–tinh hoàn','Vì thực bào không hề được bài nêu','Vì Sertoli chỉ có chức năng biến thành tinh trùng','Vì tất cả chức năng Sertoli chỉ là vận chuyển qua niệu đạo'], 'Slide 10 liệt kê nhiều nhóm chức năng; kiểm tra một nhóm không bao quát toàn bộ.', ['Thực bào có trong danh sách.','Sertoli được mô tả là tế bào điều dưỡng.','Không phải danh sách chức năng của Sertoli.'])
add('m10','tichhop','duongdan-vs-sinhtinh','h',[5,12],'Một mô hình ngừng đường đi ở ống dẫn tinh nhưng vẫn giữ hoạt động tế bào trong ống sinh tinh. Phân biệt nào đúng?', ['Sinh tinh tại ống sinh tinh và đường vận chuyển qua ống dẫn tinh là hai khâu khác nhau','Ngừng ống dẫn tinh đồng nghĩa ống sinh tinh đổi thành niệu quản','Hai tên ống thực ra chỉ cùng một vị trí','Tinh trùng phải được tạo trực tiếp trong bàng quang để bù'], 'Slide 5 mô tả tạo tế bào trong ống sinh tinh; slide 12 mô tả đường dẫn. Không suy diễn thêm hậu quả lâm sàng từ mô hình.', ['Không có biến đổi cấu trúc đó trong nguồn.','Hai cấu trúc được chỉ ở vị trí khác nhau.','Bài không nêu tạo tinh trùng ở bàng quang.'])
add('m10','tichhop','so-sanh-giao-tu','h',13,'Trong sơ đồ so sánh sinh giao tử ở slide 13, sau giảm phân, dòng tinh cho các tế bào có thể biệt hóa thành tinh trùng còn dòng noãn có thể cực. Phân tích nào phù hợp?', ['Cùng có giảm phân nhưng cách phân bố sản phẩm không được vẽ giống nhau ở hai dòng','Mỗi dòng đều chỉ tạo một tinh trùng và ba noãn','Dòng tinh tạo thể cực rồi thành noãn','Dòng noãn không có giảm phân I hoặc II'], 'Slide 13 vẽ dòng tinh phân nhánh thành bốn tiền tinh trùng, còn dòng noãn có tế bào lớn và thể cực. Đây là so sánh nằm ngay trong tài liệu sinh tinh.', ['Không phải sản phẩm được vẽ.','Trộn hai dòng tế bào.','Cả hai cột đều có các mức GP I và GP II.'])
banks['m10']['limitations']=['40 câu; nguồn14 slide không đủ cơ sở để khẳng định có100 ý kiểm tra riêng biệt.','Các nội dung hình đã đọc chỉ được chuyển thành câu chữ; không suy thêm thời gian sinh tinh, hormone Leydig hoặc cơ chế vi ống9+2 vì tài liệu không nêu rõ.','Không lấy chi tiết tín hiệu có phân biệt loài ở slide11 làm cơ chế chung ở người.','Chưa hoàn tất lượt3 độc lập.']

